@Testcontainers
class PrivateCaseReviewMigrationIT {
 @Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:74935e72241653ca55e0414067e6d8763aceb8a810eb51b452253ec3dcfc4336").asCompatibleSubstituteFor("postgres"));
 @Test void populated67RepeatedMigrationPreservesBothCountryRequestsAndDoesNotEnrollAdmins(){
  Flyway.configure().dataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword()).target("20261021150000").cleanDisabled(true).load().migrate();var ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());var jdbc=new JdbcTemplate(ds);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));Instant now=Instant.parse("2026-10-22T12:00:00Z");var ids=new UuidGenerator(Clock.fixed(now,ZoneOffset.UTC));UUID platform=ids.next();tx.executeWithoutResult(s->{jdbc.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES(?,'PLATFORM_ADMIN','synthetic-private-migration@example.com',true,'Synthetic','ACTIVE')",platform);jdbc.update("INSERT INTO platform_account(id) VALUES(?)",platform);});
  for(String country:List.of("RS","BA")){UUID actor=ids.next(),org=ids.next(),request=ids.next();tx.executeWithoutResult(s->{jdbc.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES(?,'BUSINESS',?,true,'Synthetic','ACTIVE')",actor,actor+"@example.com");jdbc.update("INSERT INTO organization(id,type,country,currency,display_name,legal_name,registration_identifier,address_line1,address_city,address_postal_code,address_country,default_language,state,owner_account_id) VALUES(?,'BUYER',?,?,'Synthetic','Synthetic','SYN-PRIVATE-MIGRATION','Synthetic','Synthetic','11000',?,?,'ACTIVE',?)",org,country,country.equals("RS")?"RSD":"BAM",country,country.equals("RS")?"sr-Latn-RS":"bs-Latn-BA",actor);jdbc.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,'OWNER')",actor,org);});jdbc.update("INSERT INTO privacy_case(id,requester_id,organization_id,country,kind,private_reason,created_at) VALUES(?,?,?,?,'REDACTION','Synthetic private migration request',?)",request,actor,org,country,Timestamp.from(now));jdbc.update("INSERT INTO privacy_case_creation(id,requester_id,organization_id,country,payload_digest,created_at,original_response) VALUES(?,?,?,?,decode(repeat('a',64),'hex'),?,jsonb_build_object('id',?::text,'organizationId',?::text,'state','REQUESTED','revision','synthetic','kind','REDACTION','createdAt','2026-10-22T12:00:00.000Z'))",request,actor,org,country,Timestamp.from(now),request,org);jdbc.update("INSERT INTO audit_event(id,actor_type,actor_id,organization_id,country,action,resource_type,resource_id,outcome,request_id,occurred_at,changed_fields) VALUES(?,'BUSINESS',?,?,?,'PRIVACY_CASE_REQUESTED','PRIVACY_CASE',?,'SUCCESS',?,?,ARRAY['state'])",ids.next(),actor,org,country,request,ids.next(),Timestamp.from(now));}
  var before=new HashMap<String,List<String>>();for(String table:List.of("account_identity","platform_account","organization","business_account","privacy_case","privacy_case_creation","privacy_case_metadata","audit_event"))before.put(table,jdbc.queryForList("SELECT (to_jsonb(r)-'privacy_retired_at')::text FROM "+table+" r ORDER BY to_jsonb(r)::text",String.class));MigrationCommand.migrate(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());MigrationCommand.migrate(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());
  for(var entry:before.entrySet())assertThat(jdbc.queryForList("SELECT (to_jsonb(r)-'privacy_retired_at')::text FROM "+entry.getKey()+" r ORDER BY to_jsonb(r)::text",String.class)).as(entry.getKey()).isEqualTo(entry.getValue());for(String table:List.of("privacy_operator","privacy_operator_configuration_event","privacy_review_access","privacy_review_read"))assertThat(jdbc.queryForObject("SELECT count(*) FROM "+table,Integer.class)).isZero();assertThat(jdbc.queryForObject("SELECT prosecdef FROM pg_proc WHERE oid='public.read_privacy_review(uuid,bytea,uuid,uuid,text,timestamptz)'::regprocedure",Boolean.class)).isTrue();assertThat(jdbc.queryForObject("SELECT NOT EXISTS(SELECT 1 FROM pg_proc p,LATERAL aclexplode(p.proacl) a WHERE p.oid='public.read_privacy_review(uuid,bytea,uuid,uuid,text,timestamptz)'::regprocedure AND a.grantee=0 AND a.privilege_type='EXECUTE')",Boolean.class)).isTrue();new DatabaseReadiness(ds).verifySchema();
 }
}
